    with open(R + path, 'w', newline='') as f:
        wr = csv.writer(f, delimiter='\t', lineterminator='\n')
        wr.writerow(header)
        for r in rows:
            assert len(r) == len(header), (path, r[0], len(r))
            wr.writerow(r)


